function previewCard(t,p,from,to,lane,total){const top=Math.max(0,M.mins(p.start)-from),height=Math.max(12,Math.min(to,M.mins(p.end))-Math.max(from,M.mins(p.start)));return `<article class="event-card ux-event fact-preview ${height<44?'compact':''} ${p.outcome==='missed'?'preview-missed':''}" style="--card-color:${t.color||M.color(t.id)};top:${top*timelineScale()}px;height:${height*timelineScale()-2}px;left:calc(${lane/total*100}% + 2px);right:calc(${100-(lane+1)/total*100}% + 2px)" data-action="preview-options" data-id="${t.id}" data-part="${p.id}" data-preview-date="${p.date}" data-preview-start="${p.start}" data-preview-end="${p.end}" data-visible-start="${Math.max(from,M.mins(p.start))}" data-visible-end="${Math.min(to,M.mins(p.end))}" role="button" tabindex="0" aria-label="Предварительный факт: ${E(t.title)}, ${p.start}–${p.end}"><div class="preview-fill"></div><div class="event-title">${E(t.title)}</div><div class="event-time">${p.start}–${p.end}</div><div class="event-meta">${p.outcome==='missed'?'Не выполнено':ST[t.status||'pending']}</div><span class="preview-timer"></span><svg class="preview-outline" width="100%" height="100%" aria-hidden="true"><rect x="1.5" y="1.5" width="calc(100% - 3px)" height="calc(100% - 3px)" rx="5"/></svg></article>`;}
function updatePreviews(now){for(const el of $$('[data-preview-date]')){const start=new Date(el.dataset.previewDate+'T'+el.dataset.previewStart+':00').getTime();const end=el.dataset.previewEnd==='24:00'?new Date(M.shift(el.dataset.previewDate,1)+'T00:00:00').getTime():new Date(el.dataset.previewDate+'T'+el.dataset.previewEnd+':00').getTime();const seconds=Math.max(0,Math.floor((Math.min(now.getTime(),end)-start)/1000));const active=now.getTime()>=start&&now.getTime()<end,started=now.getTime()>=start;el.classList.toggle('preview-active',active&&!el.classList.contains('preview-missed'));el.classList.toggle('preview-started',started);const minute=(now.getTime()-new Date(el.dataset.previewDate+'T00:00:00').getTime())/60000;const fraction=Math.max(0,Math.min(1,(minute-Number(el.dataset.visibleStart))/(Number(el.dataset.visibleEnd)-Number(el.dataset.visibleStart))));el.style.setProperty('--preview-progress',fraction*100+'%');$('.preview-timer',el).textContent=started?`${Math.floor(seconds/3600)}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`:'';}}
function previewOptions(id,part){const t=find(id),p=t?.plans.find(x=>x.id===part);if(!p)return;if(p.outcome==='missed'){missedOptions(id,part);return;}const extra=`data-part="${E(part)}"`;openContext(`<div class="note-options">${btn('preview-confirm','Завершить',id,'secondary-button',extra)}${btn('preview-session','Завершить в другое время',id,'secondary-button',extra)}${btn('preview-missed','Не выполнено',id,'secondary-button',extra)}${btn('task','Изменить…',id,'secondary-button',extra)}${btn('move-task','Переместить в список…',id,'secondary-button')}${btn('archive-task','В архив',id,'secondary-button')}${btn('delete-task','Удалить',id,'danger-button')}</div>`);}
function missedOptions(id,part){openContext(`<div class="note-options">${btn('missed-reschedule','Установить задачу на другое время…',id,'secondary-button',`data-part="${E(part)}"`)}${btn('delete-task','Удалить задачу из списка',id,'danger-button')}</div>`);}
function missedReschedule(id,part){const p=find(id)?.plans.find(p=>p.id===part);if(!p)return;openModal('Установить задачу на другое время',`<form id="missed-reschedule-form" data-id="${E(id)}" data-part="${E(part)}" class="form-grid">${input('Дата','date',M.day(),'date','required')}${input('Начало','start',p.start,'time','required')}${input('Окончание','end',p.end==='24:00'?'23:59':p.end,'time','required')}</form>`,btn('close','Отмена')+btn('save-missed-reschedule','Создать задачу','','primary-button'));}
function confirmPreview(id,part){const t=find(id),p=t?.plans.find(x=>x.id===part);if(!p)return;const now=new Date(),start=new Date(p.date+'T'+p.start+':00'),end=p.date<M.day()?M.mins(p.end):p.date>M.day()?M.mins(p.start):Math.min(M.mins(p.end),now.getHours()*60+now.getMinutes());const minutes=Math.max(0,end-M.mins(p.start));openModal('Подтвердить фактическое время',`<p>${E(t.title)}</p><p>${E(dateText(p.date))} · ${p.start}–${M.clock(Math.max(M.mins(p.start),end))}</p><p>Учесть ${duration(minutes)} и завершить событие?</p>`,btn('close','Отмена')+btn('preview-save','Подтвердить',id,'primary-button',`data-part="${E(part)}" data-end="${M.clock(Math.max(M.mins(p.start),end))}"`));}
let realDay=M.day();
function updateClock(){rollUnscheduled();const dayNow=M.day();if(dayNow!==realDay){const previous=realDay;realDay=dayNow;if(view.date===previous)view.date=dayNow;if(view.reportDate===previous)view.reportDate=dayNow;render();return;}const now=new Date();updatePreviews(now);updateCurrentTicker(now);const minute=now.getHours()*60+now.getMinutes(),text=M.clock(minute);$$('[data-now-line]').forEach(el=>{const visible=view.date===M.day()&&minute>=S().settings.startHour*60&&minute<S().settings.endHour*60;el.hidden=!visible;el.style.top=((minute-S().settings.startHour*60+now.getSeconds()/60)*timelineScale())+'px';$('[data-now-label]',el).textContent=text;});}
