function taskMatches(t,filter){const b=M.bucket(t),today=M.day(),dates=[...new Set([t.plannedDate,...t.plans.map(p=>p.date)].filter(Boolean))];if(['archive','trash'].includes(filter))return b===filter;if(b!=='active')return false;if(filter==='today')return dates.includes(today)||(!t.done&&dates.some(d=>d<today))||(!!t.deadline&&t.deadline<=today&&!t.done);if(filter==='upcoming')return (dates.some(d=>d>today)||t.deadline>today)&&!t.done;if(filter==='undated')return !dates.length&&!t.done;return true;}
