 const toolbar=`<div class="reminders-toolbar"><div class="task-view-tabs">${tabs.map(([k,l])=>btn('task-filter',l,k,`quiet-button ${filter===k?'selected':''}`)).join('')}${btn('task-views','···','','quiet-button','aria-label="Другие представления"')}</div>${btn('new-list','+','','calendar-add new-list-button','aria-label="Создать список"')}</div>`;
