 return toolbar+quick+`<div class="selection-bar">${view.selecting?btn('select-mode','Завершить выбор'):''}${view.selecting&&view.selection.size?btn('bulk-options',`Действия (${view.selection.size})`):''}</div><div class="reminder-lists ${aside?'aside-lists':''}">${groups.map(({list:l,tasks})=>{const visible=tasks.filter(t=>!t.done||(l?l.showCompleted:view.showCompleted)),completed=tasks.filter(t=>t.done).length;return `<section class="surface-card reminder-list" ${l?`data-list-drop="${l.id}"`:''}><div class="list-header" ${l?`data-list-drag="${l.id}"`:''}><h2>${E(l?.name||({today:'Задачи дня',upcoming:'Предстоящие',undated:'Без даты',archive:'Отдельные напоминания',trash:'Отдельные напоминания'}[filter]||'Задачи'))}</h2>${l?`<div class="list-actions">${btn('list-options','···',l.id,'list-more','aria-label="Действия со списком"')}${M.listBucket(l)==='active'?btn('new-task','+',l.id,'list-add','aria-label="Добавить задачу"'):''}${btn('collapse-list',`<svg viewBox="0 0 24 24"><path d="${l.collapsed?'m9 6 6 6-6 6':'m6 9 6 6 6-6'}"/></svg>`,l.id,'list-collapse',`aria-label="${l.collapsed?'Развернуть':'Свернуть'}" aria-expanded="${!l.collapsed}"`)}</div>`:''}</div><div class="list-body" ${l?.collapsed?'hidden':''}>${taskRows(visible)||'<div class="empty-state">Задач пока нет</div>'}${!['archive','trash'].includes(filter)?`<div class="list-footer">${btn('new-task','+ Добавить задачу',l?.id||'')}${completed?btn('completed',`${(l?l.showCompleted:view.showCompleted)?'Скрыть':'Показать'} завершённые (${completed})`,l?.id||''):''}</div>`:completed?`<div class="list-footer">${btn('completed',`${(l?l.showCompleted:view.showCompleted)?'Скрыть':'Показать'} завершённые (${completed})`,l?.id||'')}</div>`:''}</div></section>`;}).join('')||'<div class="empty-state">Здесь пока пусто</div>'}</div>`;
