// Empty-track creation: tap/click = one hour, hold then drag = chosen interval.
let creation=null;
function creationMinute(g,y){const from=S().settings.startHour*60,to=S().settings.endHour*60;return Math.max(from,Math.min(to,Math.floor(((y-g.track.getBoundingClientRect().top)/timelineScale()+from)/15)*15));}
function cancelCreation(){if(!creation)return;clearTimeout(creation.timer);creation.preview?.remove();creation=null;}
function paintCreation(g,y){const at=creationMinute(g,y),to=S().settings.endHour*60;g.start=Math.min(g.anchor,at);g.end=Math.min(to,Math.max(g.anchor+15,at));if(!g.moved){g.start=g.anchor;g.end=Math.min(to,g.anchor+S().settings.defaultDuration);}g.preview.style.top=((g.start-S().settings.startHour*60)*timelineScale())+'px';g.preview.style.height=((g.end-g.start)*timelineScale())+'px';g.preview.textContent=M.clock(g.start)+'–'+M.clock(g.end);}
function activateCreation(g){if(creation!==g)return;g.active=true;g.preview=document.createElement('div');g.preview.className='calendar-create-preview';g.track.append(g.preview);try{g.track.setPointerCapture(g.id);}catch(_){}paintCreation(g,g.y);}
